mapper.select:
SELECT word_id, english, chinese, part_of_speech, source, owner_id
FROM words
WHERE word_id = #{wordId}

SELECT word_id, english, chinese, part_of_speech, source, owner_id
FROM words
WHERE source = 'custom' AND owner_id = #{ownerId}

SELECT word_id, english, chinese, part_of_speech, source, owner_id
FROM words
WHERE source = 'builtin' AND word_id <> #{excludeWordId}
ORDER BY RAND()
LIMIT #{limit}

SELECT w.word_id, w.english, w.chinese, w.part_of_speech,
       COALESCE(p.proficiency, 0) AS proficiency
FROM words w
LEFT JOIN user_word_progress p ON p.word_id = w.word_id AND p.user_id = #{userId}
WHERE w.source = 'custom' AND w.owner_id = #{userId}
